s=s[:start]+'''function dataBanner(r){const d=r.data_status||{state:'empty',label:'尚无平台指标',message:'未返回的指标不补零。'};return `<section class="vc-data-status" data-case-data-status data-state="${esc(d.state)}" role="status"><strong>${esc(d.label)}</strong><p>${esc(d.message)}${d.has_data&&d.state!=='ready'?' · 下方仍保留上次已取得的数据。':''}</p></section>`}
function providerOutputs(r){return `<div data-provider-output>${metricsOf(r).map(m=>`<div class="vc-row" data-metric="${m.key}"><span class="vc-row-label">${m.label}${m.key==='gmv'?'（估算）':''}</span><div class="vc-row-content"><div class="vc-row-value">${esc(metricDisplay(m))}</div><small>${esc(m.source)}${m.scope?' · '+esc(m.scope):''}${m.collected?' · '+esc(date(m.collected)):''}</small></div></div>`).join('')}<div class="vc-row"><span class="vc-row-label">数据采集时间</span><div class="vc-row-content"><div class="vc-row-value">${esc(date(r.data_status?.collected||r.source.kalodata?.collected||r.source.collected))}</div></div></div></div>`}
function commercialRows(r){return (r.commercial||[]).map(m=>{const value=m.missing?'未提供':m.kind==='ratio'?new Intl.NumberFormat('zh-CN',{style:'percent',maximumFractionDigits:2}).format(m.value):m.kind==='text'?m.value:fmt(m.value);return `<div class="vc-row" data-commercial="${esc(m.key)}"><span class="vc-row-label">${esc(m.label)}</span><div class="vc-row-content"><div class="vc-row-value">${esc(value)}</div><small>${esc(m.source)}${!m.missing?' · '+esc(m.endpoint)+' · '+esc(m.scope):''}${m.note?' · '+esc(m.note):''}</small></div></div>`}).join('')}
function kalodataFacts(r){const k=r.source.kalodata;return `<section class="vc-section" data-provider-facts><h4>平台指标</h4>${providerOutputs(r)}<details class="vc-commercial"><summary>商业与投放详情 · 接口实际字段</summary><p class="vc-muted">仅显示该视频实际返回的字段。category_ids 是排行榜筛选参数，不是视频商品类目；未返回的品类由有证据的AI建议补缺。</p><div data-commercial-output>${commercialRows(r)}</div></details><details class="vc-platform-data"><summary>更新指标与来源说明</summary><p class="vc-muted">${k?esc(k.period_start+' — '+k.period_end+'（UTC）'):'当前没有Kalodata详情结果。'}美国市场 · USD · 第三方估算，不是结算订单；不与累计快照混算。收藏数需已有公开快照或人工补充。按视频ID精确查询 /video/detail；/video/rank 是榜单筛选，不能保证查到任意链接。</p><div class="vc-actions"><select data-kalodata-days aria-label="Kalodata 查询区间"><option value="30">近30天</option><option value="7">近7天</option></select><button type="button" data-process="kalodata">${k?'更新':'调取'}资料 · 约0.1 credits</button></div></details></section>`}
''' + s[end:]
